function [output,fg] = spm_check_registration_evalc(a,b) %#ok<INUSD> 
%SPM_CHECK_REGISTRATION_EVALC Executes SPM's 'Check Registration' function
%   while capturing its command window output and returning the figure handle.
%
%   [OUTPUT, FG] = SPM_CHECK_REGISTRATION_EVALC(A, B)
%
%   This is a utility wrapper that calls the SPM function `spm_check_registration`,
%   which is used to visualize the coregistration between two or more NIfTI
%   volumes. The core feature is the use of `evalc` to suppress the standard
%   command window output generated by `spm_check_registration` and capture
%   it as a string, while still allowing the visualization figure to open.
%
%   Input Arguments:
%   A - Full path to a NIfTI file (or a cell array of NIfTI paths) to load
%       and display in the Check Registration window.
%   B - (Optional) Full path to a second NIfTI file (or cell array) to also
%       load and display. If omitted, only A is displayed.
%
%   Output Arguments:
%   OUTPUT - A string containing all the text that `spm_check_registration`
%            would normally print to the MATLAB command window (captured via `evalc`).
%   FG     - The handle to the SPM Graphics figure window where the images are displayed.
%
%   Dependencies: Requires the SPM (Statistical Parametric Mapping) toolbox
%   to be correctly set up and added to the MATLAB path.
%   - `spm_figure`
%   - `spm_check_registration`
%
%   Author: Pratik Jain

fg = spm_figure('GetWin','Graphics');
if nargin == 1
    output = evalc('spm_check_registration(a)');  % Plot the two images using Check Registration
elseif nargin == 2
    output = evalc('spm_check_registration(a,b)');  % Plot the two images using Check Registration
end